010end\010\010local function UpdateQuestXP(options)\010  if runtime.questXPDirty then\010    local scanAt = Clock()\010    if questXP.lastScanAt <= 0\010        or scanAt < questXP.lastScanAt\010        or (scanAt - questXP.lastScanAt) >= QUEST_SCAN_INTERVAL then\010      local completed, incomplete, scanned, entries, debugText =\010        ScanQuestLog(options.questDebug, options.questXPSource)\010\010      questXP.rawCompletedXP = NonNegativeNumber(completed)\010      questXP.rawIncompleteXP = NonNegativeNumber(incomplete)\010      questXP.scannedQuestCount = NonNegativeNumber(scanned)\010      questXP.questLogEntries = NonNegativeNumber(entries)\010      questXP.debugQuestText = type(debugText) == \"string\" and debugText or \"\"\010      questXP.lastScanAt = scanAt\010      if options.questDebug then\010        local scanTime = WallClock()\010        questXP.lastScanText = (scanTime > 0 and date)\010          and date(\"%H:%M:%S\", scanTime) or tostring(scanTime)\010      end\010      questXP.hasScan = true\010      runtime.questXPDirty = nil\010    end\010  end\010\010  local effectiveMultiplier = tonumber(options.questXPEffectiveMultiplier) or 1\010  questXP.completedQuestXP = math.floor(\010    questXP.rawCompletedXP * effectiveMultiplier + 0.5\010  )\010  questXP.incompleteQuestXP = math.floor(\010    questXP.rawIncompleteXP * effectiveMultiplier + 0.5\010  )\010end\010\010-- Session and /played state machines.\010local function UpdateSession(now, player, mode)\010  if session then\010    session.startTime = tonumber(session.startTime) or now\010    session.gainedXP = NonNegativeNumber(session.gainedXP)\010    session.paused = session.paused == true\010    session.pausedAt = session.paused and (tonumber(session.pausedAt) or now) or nil\010    session.hasXPBaseline = session.hasXPBaseline == true\010  end\010\010  if mode == \"reset\" or not session then\010    session = {\010      startTime = now,\010      gainedXP = 0,\010      paused = false,\010      lastLevel = player.level,\010      hasXPBaseline = false,\010    }\010    runtime.session = session\010  elseif mode == \"gain\" and not session.paused and session.hasXPBaseline then\010    local previousLevel = tonumber(session.lastLevel) or player.level\010    local previousXP = tonumber(session.lastXP) or player.currentXP\010    local previousMax = tonumber(session.maxXP) or player.maxXP\010    local gained = 0\010    if player.level > previousLevel then\010      gained = math.max(0, previousMax - previousXP + player.currentXP)\010    elseif player.level == previousLevel and player.currentXP >= previousXP then\010      gained = player.currentXP - previousXP\010    end\010    if gained > 0 then session.gainedXP = session.gainedXP + gained end\010  end\010\010  if mode or not session.hasXPBaseline then\010    local hasXP = player.maxXP > 0\010    session.lastLevel, session.lastXP, session.maxXP, session.hasXPBaseline =\010      player.level, hasXP and player.currentXP or nil, hasXP and player.maxXP or nil, hasXP\010  end\010  StoreSession(now)\010end\010\010local function ClearPlayedRequest()\010  playedRuntime.requested, playedRuntime.requestAt, playedRuntime.requestFailed =\010    false, 0, false\010end\010\010local function RequestPlayed(now, reset, enabled, optionsOpen)\010  if reset then\010    ClearPlayedRequest()\010  elseif playedRuntime.requested\010      and (now - playedRuntime.requestAt) >= PLAYED_REQUEST_TIMEOUT then\010    playedRuntime.requested, playedRuntime.requestFailed = false, true\010  end\010\010  if not enabled or optionsOpen or playedRuntime.requested or playedRuntime.requestFailed\010      or (playedTime.initialized == true and playedRuntime.sampleAt > 0 and not reset)\010      or (WeakAuras.IsPaused and WeakAuras.IsPaused()) then\010    return\010  end\010  if type(RequestTimePlayed) ~= \"function\" then\010    playedRuntime.requestFailed = true\010    return\010  end\010\010  playedRuntime.requested, playedRuntime.requestAt, playedRuntime.requestFailed =\010    true, now, false\010  RequestTimePlayed()\010end\010\010local function UpdatePulseState(options)\010  local frame = runtime.controllerFrame\010  if not frame then return end\010\010  options = options or ReadOptions()\010  local shouldRun = not not (cache.xpDataPending or resetMenu.optionsOpen or (\010    cache.displayActive ~= false and (\010      (runtime.questXPDirty and options.needsQuestXP)\010      or options.showPlayedTimeText\010      or (not (session and session.paused)\010        and (options.showSessionText or options.showLevelingText))\010    )\010  ))\010  if cache.pulseActive == shouldRun then return end\010\010  cache.pulseActive = shouldRun\010  if shouldRun then frame:Show() else frame:Hide() end\010end\010\010-- Reset/Pause is an independent UI overlay, not part of the TSU state.\010local function SetControlVisible(control, visible)\010  if not control then return end\010  control:EnableMouse(not not visible)\010  if visible then control:Show() else control:Hide() end\010end\010\010local function HideResetUI()\010  SetControlVisible(resetMenu.left, false); SetControlVisible(resetMenu.right, false); SetControlVisible(resetMenu.button, false)\010  if runtime.hoverFrame then runtime.hoverFrame:Hide() end\010  resetMenu.hoverOutsideSince = nil\010end\010\010local AttachResetUI\010\010local RESET_R, RESET_G, RESET_B = 0, 0.14509804546833, 0.7607843875885\010local PAUSE_R, PAUSE_G, PAUSE_B = 0.64313727617264, 0.64313727617264, 0.64313727617264\010local PAUSED_R, PAUSED_G, PAUSED_B = 1, 0.69411766529083, 0\010local COMPLETE_TEXT_COLOR = \"|cFFFF9700\"\010local INCOMPLETE_TEXT_COLOR = \"|cFFFFD24F\"\010local RESTED_TEXT_COLOR = \"|cFF4F90FF\"\010local PAUSED_TEXT_COLOR = \"|cFFFFB100\"\010local COLOR_END = \"|r\"\010\010local function SetResetActionColor(button, r, g, b)\010  if button and button.dhxbBackground then button.dhxbBackground:SetVertexColor(r, g, b, 1) end\010end\010\010local function UpdateResetMenuLabels()\010  local paused, right = session and session.paused, resetMenu.right\010  if right and right.dhxbLabel then\010    right.dhxbLabel:SetText(paused and \"Unpause Session\" or \"Pause Session\")\010  end\010  SetResetActionColor(resetMenu.left, RESET_R, RESET_G, RESET_B)\010  SetResetActionColor(right, paused and PAUSED_R or PAUSE_R,\010    paused and PAUSED_G or PAUSE_G, paused and PAUSED_B or PAUSE_B)\010end\010\010-- Mouse focus, not just mouse coordinates, determines which UI receives hover.\010-- This avoids retaining the buttons while another addon's overlay covers them.\010local HOVER_CHECK_INTERVAL, HOVER_CLOSE_GRACE = 0.10, 0.15\010\010local function MouseInsideClient()\010  if type(GetCursorPosition) ~= \"function\" or not UIParent\010      or not UIParent.GetWidth or not UIParent.GetHeight then return true end\010  local x, y = GetCursorPosition()\010  if not x or not y then return false end\010  local scale = UIParent.GetEffectiveScale and UIParent:GetEffectiveScale() or 1\010  if not scale or scale <= 0 then scale = 1 end\010  x, y = x / scale, y / scale\010  return x >= 0 and y >= 0\010    and x <= UIParent:GetWidth() and y <= UIParent:GetHeight()\010end\010\010local function MouseInsideResetUI()\010  if resetMenu.dragging then return true end\010  if not MouseInsideClient() then return false end\010\010  local focus\010  if type(GetMouseFoci) == \"function\" then\010    local foci = GetMouseFoci()\010    if type(foci) == \"table\" then focus = foci[1]\010    else focus = foci end\010  end\010  if not focus and type(GetMouseFocus) == \"function\" then\010    focus = GetMouseFocus()\010  end\010\010  if focus then\010    -- Textures/font strings can be the focus; follow parent frames.\010    local depth = 0\010    while focus and depth < 32 do\010      if focus == resetMenu.button or focus == resetMenu.left\010          or focus == resetMenu.right then return true end\010      if not focus.GetParent then break end\010      focus = focus:GetParent()\010      depth = depth + 1\010    end\010    return false\010  end\010  -- If the focus API exists but reports nothing, the menu isn't hovered.\010  if type(GetMouseFoci) == \"function\" or type(GetMouseFocus) == \"function\" then\010    return false\010  end\010  -- Legacy client fallback; only used when no focus API exists.\010  return type(MouseIsOver) == \"function\" and (\010    (resetMenu.button and MouseIsOver(resetMenu.button))\010    or (resetMenu.left and MouseIsOver(resetMenu.left))\010    or (resetMenu.right and MouseIsOver(resetMenu.right))) or false\010end\010\010local function SetResetMenuOpen(open)\010  resetMenu.open = not not open\010  resetMenu.hoverOutsideSince = nil\010  UpdateResetMenuLabels()\010  AttachResetUI()\010  UpdatePulseState()\010\010  local hoverFrame = runtime.hoverFrame\010  if resetMenu.open and not hoverFrame then\010    hoverFrame = CreateFrame(\"Frame\")\010    runtime.hoverFrame = hoverFrame\010    hoverFrame:SetScript(\"OnUpdate\", function(self, elapsed)\010      self.elapsed = (self.elapsed or 0) + (elapsed or 0)\010      if self.elapsed < HOVER_CHECK_INTERVAL then return end\010      self.elapsed = self.elapsed % HOVER_CHECK_INTERVAL\010      if not resetMenu.open then self:Hide(); return end\010      if MouseInsideResetUI() then\010        resetMenu.hoverOutsideSince = nil\010      else\010        local now = Clock()\010        if not resetMenu.hoverOutsideSince then\010          resetMenu.hoverOutsideSince = now\010        elseif now - resetMenu.hoverOutsideSince >= HOVER_CLOSE_GRACE then\010          SetResetMenuOpen(false)\010        end\010      end\010    end)\010  end\010  if hoverFrame then\010    hoverFrame.elapsed = 0\010    if resetMenu.open then hoverFrame:Show() else hoverFrame:Hide() end\010  end\010end\010\010local function CloseResetMenuIfOutside()\010  if not resetMenu.open then return end\010  if MouseInsideResetUI() then\010    resetMenu.hoverOutsideSince = nil\010  else\010    resetMenu.hoverOutsideSince = resetMenu.hoverOutsideSince or Clock()\010  end\010end\010\010local function ToggleSessionPaused(now)\010  if not session then return end\010  if session.paused then\010    session.startTime = (tonumber(session.startTime) or now)\010      + math.max(0, now - (tonumber(session.pausedAt) or now))\010    session.paused, session.pausedAt = false, nil\010  else\010    session.paused, session.pausedAt = true, now\010  end\010  StoreSession(now)\010end\010\010local function HandleResetAction(control, button)\010  if not resetMenu.open or button ~= \"LeftButton\" then return end\010\010  local now, action = Clock(), control and control.dhxbAction\010  if action == \"reset\" then\010    UpdateSession(now, ReadPlayerState(ReadOptions()), \"reset\")\010  elseif action == \"pause\" then\010    ToggleSessionPaused(now)\010  end\010  UpdateResetMenuLabels()\010  Refresh()\010end\010\010local function CreateResetAction(parent, action)\010  local isReset = action == \"reset\"\010  local button = CreateFrame(\"Button\", nil, parent)\010  button.dhxbAction = action\010\010  local background = button:CreateTexture(nil, \"ARTWORK\")\010  background:SetTexture(\"Interface\\\\BUTTONS\\\\WHITE8X8\")\010  background:SetAllPoints(button)\010  button.dhxbBackground = background\010\010  local label = button:CreateFontString(nil, \"OVERLAY\", \"GameFontNormal\")\010  local lib = LibStub and LibStub(\"LibSharedMedia-3.0\", true)\010  label:SetFont((lib and lib.Fetch and lib:Fetch(\"font\", \"Expressway\", true))\010    or STANDARD_TEXT_FONT or \"Fonts\\\\FRIZQT__.TTF\", 14, \"OUTLINE\")\010  label:SetTextColor(1, 1, 1, 1)\010  label:SetShadowColor(0, 0, 0, 1)\010  label:SetShadowOffset(1, -1)\010  label:SetPoint(\"CENTER\", button, \"CENTER\", 0, 1)\010  label:SetText(isReset and \"Reset Session\" or \"Pause Session\")\010  button.dhxbLabel = label\010  SetResetActionColor(button, isReset and RESET_R or PAUSE_R,\010    isReset and RESET_G or PAUSE_G, isReset and RESET_B or PAUSE_B)\010\010  SetControlVisible(button, false)\010  return button\010end\010\010local function IsAuraFrame(frame)\010  return frame and frame.GetLeft and frame.GetRight\010    and frame.GetTop and frame.GetBottom and frame.SetPoint\010end\010\010local function StartBarDrag(_, button)\010  if button ~= \"RightButton\" then return end\010  local target = resetMenu.target\010  if not IsAuraFrame(target) or not target.SetMovable or not target.StartMoving then return end\010  target:SetMovable(true)\010  if target.SetClampedToScreen then target:SetClampedToScreen(true) end\010  target:StartMoving()\010  resetMenu.dragging = true\010end\010\010local function StopBarDrag()\010  if not resetMenu.dragging then return end\010  resetMenu.dragging = false\010\010  local target = resetMenu.target\010  if not IsAuraFrame(target) or not target.StopMovingOrSizing then return end\010  target:StopMovingOrSizing()\010  if not target.GetCenter or not UIParent then return end\010\010  local x, y = target:GetCenter()\010  local ux, uy = UIParent:GetCenter()\010  if not x or not y or not ux or not uy then return end\010  env.saved.position = env.saved.position or {}\010  env.saved.position.x, env.saved.position.y = x - ux, y - uy\010end\010\010local function BindResetControl(control, onMouseUp)\010  if not control then return end\010  control:SetScript(\"OnEnter\", function() SetResetMenuOpen(true) end)\010  control:SetScript(\"OnLeave\", CloseResetMenuIfOutside)\010  control:SetScript(\"OnMouseUp\", onMouseUp)\010  control:SetScript(\"OnDragStart\", StartBarDrag)\010  control:SetScript(\"OnDragStop\", StopBarDrag)\010  if control.RegisterForDrag then control:RegisterForDrag(\"RightButton\") end\010end\010\010function AttachResetUI()\010  local target = IsAuraFrame(env.region) and env.region\010  if not target and WeakAuras and type(WeakAuras.GetRegion) == \"function\"\010      and env.id then\010    target = WeakAuras.GetRegion(env.id, env.cloneId)\010    if not IsAuraFrame(target) and env.cloneId then target = WeakAuras.GetRegion(env.id) end\010  end\010  if not IsAuraFrame(target) then HideResetUI(); return end\010\010  resetMenu.target = target\010  if not resetMenu.dragging then\010    local pos = env.saved and env.saved.position\010    if type(pos) == \"table\" and UIParent then\010      target:ClearAllPoints()\010      target:SetPoint(\"CENTER\", UIParent, \"CENTER\", tonumber(pos.x) or 0, tonumber(pos.y) or 0)\010    end\010  end\010\010  local overlay, left, right = resetMenu.button, resetMenu.left, resetMenu.right\010  if not overlay then\010    overlay = CreateFrame(\"Button\", nil, target)\010    left, right = CreateResetAction(overlay, \"reset\"), CreateResetAction(overlay, \"pause\")\010    resetMenu.button, resetMenu.left, resetMenu.right = overlay, left, right\010    left:SetPoint(\"TOPLEFT\", overlay, \"TOPLEFT\", 0, 0)\010    left:SetPoint(\"BOTTOMRIGHT\", overlay, \"BOTTOM\", 0, 0)\010    right:SetPoint(\"TOPLEFT\", overlay, \"TOP\", 0, 0)\010    right:SetPoint(\"BOTTOMRIGHT\", overlay, \"BOTTOMRIGHT\", 0, 0)\010  end\010\010  if overlay:GetParent() ~= target then overlay:SetParent(target) end\010  BindResetControl(overlay, nil)\010  BindResetControl(left, HandleResetAction)\010  BindResetControl(right, HandleResetAction)\010  overlay:ClearAllPoints()\010  overlay:SetAllPoints(target)\010  overlay:SetFrameStrata(\"TOOLTIP\")\010  left:SetFrameStrata(\"TOOLTIP\")\010  right:SetFrameStrata(\"TOOLTIP\")\010  local level = (target:GetFrameLevel() or 0) + RESET_FRAME_LEVEL_OFFSET\010  overlay:SetFrameLevel(level)\010  left:SetFrameLevel(level + 1)\010  right:SetFrameLevel(level + 1)\010  UpdateResetMenuLabels()\010  SetControlVisible(overlay, true)\010  SetControlVisible(left, resetMenu.open)\010  SetControlVisible(right, resetMenu.open)\010end\010\010-- Display text and TSU state are built separately for easier auditing.\010local function JoinText(left, right)\010  if left ~= \"\" and right ~= \"\" then return left .. \" | \" .. right end\010  return left ~= \"\" and left or right\010end\010\010local function FormatXPLine(label, color, xp, percent)\010  return label .. \": \" .. color .. FormatNumber(xp)\010    .. \" (\" .. Percent(percent) .. \")\" .. COLOR_END\010end\010\010local function BuildDetailText(options, completedXP, incompleteXP, restedXP, maxXP, percentCompleted)\010  local percentIncomplete = maxXP > 0 and incompleteXP / maxXP * 100 or 0\010  local percentRested = maxXP > 0 and restedXP / maxXP * 100 or 0\010\010  local questText = \"\"\010  if options.showQuestText or options.showIncompleteQuestXP then\010    local completed = options.showQuestText and completedXP > 0\010      and FormatXPLine(\"Completed\", COMPLETE_TEXT_COLOR, completedXP, percentCompleted) or \"\"\010    local incomplete = options.showIncompleteQuestXP and incompleteXP > 0\010      and FormatXPLine(\"Incomplete\", INCOMPLETE_TEXT_COLOR, incompleteXP, percentIncomplete) or \"\"\010    questText = JoinText(completed, incomplete)\010    if questText == \"\" then questText = \"Quests: 0\" end\010  end\010\010  local restedText = \"\"\010  if options.showRestedText then\010    restedText = restedXP > 0\010      and FormatXPLine(\"Rested\", RESTED_TEXT_COLOR, restedXP, percentRested)\010      or \"Rested: --\"\010  end\010  local detailText = JoinText(questText, restedText)\010\010  local debugText = \"\"\010  if options.questDebug then\010    local rows = (questXP.debugQuestText or \"\") ~= \"\"\010      and questXP.debugQuestText or \"no quest rows captured\"\010    debugText =\010      \"QuestScan: \" .. tostring(questXP.lastScanText or \"--\")\010      .. \"\\nEntries: \" .. tostring(questXP.questLogEntries or 0)\010      .. \" | Scanned: \" .. tostring(questXP.scannedQuestCount or 0)\010      .. \"\\nDone: \" .. FormatNumber(questXP.completedQuestXP or 0)\010      .. \" | Open: \" .. FormatNumber(questXP.incompleteQuestXP or 0)\010      .. \" | Total: \" .. tostring(options.questXPEffectiveMultiplierText or \"x1,0\")\010      .. \"\\nRealm: \" .. tostring(options.questXPRealmMultiplierText or \"x1,0\")\010      .. \" | Bonus: \" .. tostring(options.questXPBonusPercentText or \"+0%\")\010      .. \"\\nSource: \" .. tostring(options.questXPSourceText or options.questXPSource or \"--\")\010      .. \" | Raw: \" .. tostring(options.questXPSourceRaw or \"nil\")\010      .. \" | Modern: \" .. tostring(questXP.lastModern == true)\010      .. \" | Project: \" .. tostring(WOW_PROJECT_ID or \"nil\")\010      .. \"\\nRewardAPI: \" .. tostring(type(GetQuestLogRewardXP) == \"function\")\010      .. \" | ObjectiveAPI: \" .. tostring(type(GetNumQuestLeaderBoards) == \"function\"\010        and type(GetQuestLogLeaderBoard) == \"function\")\010      .. \"\\nSample quests:\\n\" .. rows\010  end\010  return detailText, debugText\010end\010\010local function BuildPlayedText(now, atMax, enabled)\010  if not enabled then return \"\" end\010\010  if playedTime.initialized == true and playedRuntime.sampleAt > 0 then\010    local delta = math.max(0, now - playedRuntime.sampleAt)\010    local played = (atMax and playedTime.totalPlayedSeconds\010      or playedTime.levelPlayedSeconds) + delta\010    return (atMax and \"Time played: \" or \"Time this level: \")\010      .. FormatTime(played)\010  end\010  return playedRuntime.requestFailed and \"Time played: unavailable\"\010    or \"Time played: requesting...\"\010end\010\010local function CommitDisplayState(state, changed, currentXP, maxXP, atMax,\010  completedXP, shownIncomplete, restedXP, stateName)\010  local stateValue = atMax and 1 or (maxXP > 0 and currentXP or 1)\010  local stateTotal = atMax and 1 or (maxXP > 0 and maxXP or 1)\010  changed = SetField(state, \"show\", true) or changed\010  changed = SetField(state, \"progressType\", \"static\") or changed\010  changed = SetField(state, \"value\", stateValue) or changed\010  changed = SetField(state, \"total\", stateTotal) or changed\010  changed = SetField(state, \"name\", stateName) or changed\010\010  local progress = state.additionalProgress\010  if not progress or not progress[1] or not progress[2] or not progress[3] then\010    progress = {\010      { direction = \"forward\", width = 0 },\010      { direction = \"forward\", width = 0, offset = 0 },\010      { direction = \"forward\", width = 0, offset = 0 },\010    }\010    state.additionalProgress = progress\010    changed = true\010  end\010\010  local progressTotal = not atMax and maxXP > 0 and maxXP or 0\010  if progressTotal > 0 then\010    completedXP = math.min(NonNegativeNumber(completedXP), progressTotal)\010    shownIncomplete = math.min(NonNegativeNumber(shownIncomplete), progressTotal - completedXP)\010    restedXP = math.min(NonNegativeNumber(restedXP), progressTotal - completedXP - shownIncomplete)\010  else\010    completedXP, shownIncomplete, restedXP = 0, 0, 0\010  end\010\010  changed = SetField(progress, 4, nil) or changed\010  local p1, p2, p3 = progress[1], progress[2], progress[3]\010  changed = SetField(p1, \"width\", completedXP) or changed\010  changed = SetField(p1, \"offset\", nil) or changed\010  changed = SetField(p2, \"width\", shownIncomplete) or changed\010  changed = SetField(p2, \"offset\", completedXP) or changed\010  changed = SetField(p3, \"width\", restedXP) or changed\010  changed = SetField(p3, \"offset\", completedXP + shownIncomplete) or changed\010  state.changed = changed\010end\010\010local function RenderDisplay(state, options, now, player)\010  local currentXP = NonNegativeNumber(player.currentXP)\010  local maxXP = NonNegativeNumber(player.maxXP)\010  local level = NonNegativeNumber(player.level)\010  local atMax = not not player.isAtMaxLevel\010  local remainingXP = math.max(0, maxXP - currentXP)\010  local completedXP = options.showQuestText\010    and NonNegativeNumber(questXP.completedQuestXP) or 0\010  local incompleteXP = NonNegativeNumber(questXP.incompleteQuestXP)\010  local shownIncomplete = options.showIncompleteQuestXP and incompleteXP or 0\010  local restedXP = options.showRestedText\010    and NonNegativeNumber(player.restedXP) or 0\010  local percentCompleted = maxXP > 0 and completedXP / maxXP * 100 or 0\010\010  local levelText = \"Level \" .. tostring(level)\010  local xpText, barXPText, percentText, barPercentText\010  if atMax then\010    xpText, barXPText, percentText, barPercentText =\010      \"Max Level\", \"Max Level\", \"100.0%\", \"100.0%\"\010  elseif maxXP <= 0 then\010    xpText, barXPText, percentText, barPercentText =\010      \"XP unavailable\", \"XP unavailable\", \"--\", \"--\"\010  else\010    local percentXP = currentXP / maxXP * 100\010    xpText = FormatBarXP(currentXP) .. \" / \" .. FormatBarXP(maxXP)\010    percentText = Percent(percentXP)\010    barXPText = xpText .. \" (\" .. FormatBarXP(remainingXP) .. \")\"\010    barPercentText = completedXP > 0\010      and (percentText .. \" (\" .. Percent(percentXP + percentCompleted) .. \")\")\010      or percentText\010  end\010\010  local detailText, debugText = BuildDetailText(\010    options, completedXP, incompleteXP, restedXP, maxXP, percentCompleted)\010\010  local sessionTime = math.max(0,\010    ((session.paused and tonumber(session.pausedAt)) or now) - session.startTime)\010  local sessionXP = NonNegativeNumber(session.gainedXP)\010  local levelingText = \"\"\010  if options.showLevelingText then\010    local xpPerHour = not session.paused and sessionTime > 0 and sessionXP > 0\010      and math.floor((sessionXP / sessionTime) * 3600 + 0.5) or 0\010    if not atMax and remainingXP > 0 and xpPerHour > 0 then\010      local timeToLevel = math.max(1, math.floor((remainingXP / xpPerHour) * 3600 + 0.5))\010      levelingText = \"Leveling in: \" .. FormatTime(timeToLevel)\010        .. \" (\" .. FormatNumber(xpPerHour) .. \" XP/h)\"\010    else\010      levelingText = \"Leveling in: N/A\"\010    end\010  end\010\010  local sessionStatsText = \"\"\010  if options.showSessionText then\010    sessionStatsText = \"Time this session: \" .. FormatTime(sessionTime)\010      .. (session.paused and \" (Paused)\" or \"\")\010      .. \" | +\" .. FormatNumber(sessionXP) .. \" XP\"\010    if session.paused then\010      sessionStatsText = PAUSED_TEXT_COLOR .. sessionStatsText .. COLOR_END\010    end\010  end\010\010  local changed, text = false, displayText\010  changed = SetField(text, \"levelText\", levelText) or changed\010  changed = SetField(text, \"barXPText\", barXPText) or changed\010  changed = SetField(text, \"barPercentText\", barPercentText) or changed\010  changed = SetField(text, \"levelingText\", levelingText) or changed\010  changed = SetField(text, \"detailText\", detailText) or changed\010  changed = SetField(text, \"debugText\", debugText) or changed\010  changed = SetField(text, \"totalPlayedText\",\010    BuildPlayedText(now, atMax, options.showPlayedTimeText)) or changed\010  changed = SetField(text, \"sessionStatsText\", sessionStatsText) or changed\010\010  CommitDisplayState(\010    state, changed, currentXP, maxXP, atMax, completedXP, shownIncomplete,\010    restedXP, levelText .. \"  \" .. xpText .. \"  \" .. percentText\010  )\010end\010\010local function ProcessEvent(eventName, options, now, player, optionsOpen, ...)\010  if eventName == \"TIME_PLAYED_MSG\" then\010    local total, level = ...\010    total = tonumber(total) or tonumber(_G and _G.arg1)\010    level = tonumber(level) or tonumber(_G and _G.arg2)\010    if total and level then\010      playedTime.totalPlayedSeconds, playedTime.levelPlayedSeconds =\010        math.max(0, total), math.max(0, level)\010      playedTime.initialized, playedRuntime.sampleAt = true, now\010      ClearPlayedRequest()\010    end\010  elseif eventName == \"PLAYER_ENTERING_WORLD\" then\010    UpdateSession(now, player, \"baseline\")\010    runtime.questXPDirty = true\010  elseif eventName == \"PLAYER_XP_UPDATE\" then\010    UpdateSession(now, player, \"gain\")\010  elseif eventName == \"PLAYER_LEVEL_UP\" then\010    UpdateSession(now, player, \"gain\")\010    if pl